const menu=document.querySelector('.menu'),mobile=document.querySelector('#mobile-nav');function closeMenu(){mobile.hidden=true;menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open menu')}menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';mobile.hidden=!open;menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close menu':'Open menu')});mobile.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();menu.focus()}});document.querySelector('#inquiry').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const d=new FormData(form),body=`Hello DJ,\n\n${d.get('message')}\n\nName: ${d.get('name')}\nEmail: ${d.get('email')}\nPhone: ${d.get('phone')||'Not provided'}`;const status=document.querySelector('#form-status');status.hidden=false;status.textContent='Review the draft and press Send in your email app. If no app opens, email DJ@brkpnt.co or call 707.332.0604. Your inquiry has not been submitted through this website.';window.location.href=`mailto:DJ@brkpnt.co?subject=${encodeURIComponent('Investigation inquiry')}&body=${encodeURIComponent(body)}`});
